#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void) {
    /* 1. Set APB2 divider = 2 (PPRE2 = /2, bitfield value 0b100 = RCC_CFGR_PPRE2_DIV2) */
    /* SYSCLK = 170 MHz, AHB = 170 MHz, PCLK2 = 85 MHz. Timer clock TIM1CLK = 2 * PCLK2 = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_PPRE2_Msk) | RCC_CFGR_PPRE2_DIV2;

    /* 2. Enable clocks for GPIOA and TIM1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 3. Configure PA8 as Alternate Function (AF6 - TIM1_CH1) */
    /* MODER8 = 10 (AF mode) */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2U << GPIO_MODER_MODE8_Pos);
    /* AFRH8 = AF6 */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << GPIO_AFRH_AFSEL8_Pos)) | (6U << GPIO_AFRH_AFSEL8_Pos);
    /* High speed output */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* 4. Configure TIM1 for 20 kHz PWM, 25% duty cycle */
    /* f_PWM = TIM1_CLK / ((PSC + 1) * (ARR + 1)) = 170 MHz / ((0 + 1) * (8499 + 1)) = 20 kHz */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;
    /* Duty = CCR1 / (ARR + 1) = 2125 / 8500 = 25% */
    TIM1->CCR1 = 2125U;

    /* PWM mode 1 on CH1: OC1M = 0110b, enable preload OC1PE */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM1_CCMR1_OC1M_Msk | TIM1_CCMR1_CC1S_Msk)) 
                | (6U << TIM1_CCMR1_OC1M_Pos) 
                | TIM1_CCMR1_OC1PE;

    /* Enable output on Channel 1 (CC1E = 1, active high) */
    TIM1->CCER |= TIM1_CCER_CC1E;

    /* For advanced timer TIM1, Main Output Enable (MOE) in BDTR is mandatory */
    TIM1->BDTR |= TIM1_BDTR_MOE;

    /* Enable auto-reload preload */
    TIM1->CR1 |= TIM1_CR1_ARPE;

    /* Generate an update event to transfer preloaded values into active registers */
    TIM1->EGR = TIM1_EGR_UG;

    /* Enable counter */
    TIM1->CR1 |= TIM1_CR1_CEN;
}

