#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void) {
    /* 1. Set APB2 divider = 2 (PCLK2 = 85 MHz from SYSCLK 170 MHz) */
    /* When APB prescaler != 1, timer clock TIM1CLK = 2 * PCLK2 = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_PPRE2_Msk) | RCC_CFGR_PPRE2_DIV2;

    /* 2. Enable GPIOA and TIM1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 3. Configure PA8 in Alternate Function mode (AF6 -> TIM1_CH1) */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << GPIO_AFRH_AFSEL8_Pos)) | (6U << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* 4. Configure TIM1 for 20 kHz PWM, 25% duty cycle */
    /* TIM1CLK = 170 MHz, f_PWM = TIM1CLK / ((PSC + 1) * (ARR + 1)) = 170 MHz / (1 * 8500) = 20 kHz */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;
    /* Duty cycle = CCR1 / (ARR + 1) = 2125 / 8500 = 25% */
    TIM1->CCR1 = 2125U;

    /* PWM mode 1 on CH1 (OC1M = 6: 0110b), enable preload register (OC1PE) */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk))
                | (6U << TIM_CCMR1_OC1M_Pos)
                | TIM_CCMR1_OC1PE;

    /* Enable Channel 1 output */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable Main Output (MOE bit in BDTR, required for advanced timers TIM1/TIM8/TIM20) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Enable ARR preload */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Generate update event to load shadow registers */
    TIM1->EGR = TIM_EGR_UG;

    /* Enable counter */
    TIM1->CR1 |= TIM_CR1_CEN;
}

